// گام ۱ — بررسی توکن و آماده‌کردن یک درخواست embedding برای «موضوع پیشنهاد + تخصص هر استاد».
// فهرست candidates را پورتال با قواعد قطعی ساخته است (عضو همان گروه، غیر از راهنما و نویسنده).
const req = $input.first().json;
if (!$env.AGENT_TOKEN || (req.headers || {})['x-agent-token'] !== $env.AGENT_TOKEN) {
  throw new Error('Unauthorized: invalid X-Agent-Token');
}
const body = req.body || {};
const candidates = Array.isArray(body.candidates) ? body.candidates : [];
const withProfile = candidates.filter((c) => String(c.expertise || '').trim());
const withoutProfile = candidates.filter((c) => !String(c.expertise || '').trim());
const query = String(body.query_text || '').slice(0, 6000);

return [
  {
    json: {
      run_id: body.run_id,
      case: body.case || {},
      query_text: query,
      explain_top: Number(body.explain_top) || 5,
      with_profile: withProfile,
      without_profile: withoutProfile,
      embed_request: {
        model: $env.EMBEDDING_MODEL,
        input: [query, ...withProfile.map((c) => String(c.expertise))],
      },
    },
  },
];

// گام ۳ — رتبه‌بندی با شباهت کسینوسی و ساخت پرامپت «توجیه یک‌جمله‌ای» برای نفرات برتر.
const prep = $('Prepare Candidates').first().json;
const res = $input.first().json;

if (!Array.isArray(res.data) || res.data.length !== prep.with_profile.length + 1) {
  const err = res.error;
  const detail = (err && (err.message || (typeof err === 'string' ? err : JSON.stringify(err)))) || 'پاسخ ناقص';
  return [{ json: { run_id: prep.run_id, error: 'مدل embedding پاسخ نداد.', detail: String(detail).slice(0, 300) } }];
}

const vectors = res.data
  .slice()
  .sort((a, b) => (a.index || 0) - (b.index || 0))
  .map((d) => d.embedding);

function cosine(a, b) {
  let dot = 0;
  let na = 0;
  let nb = 0;
  for (let i = 0; i < a.length; i += 1) {
    dot += a[i] * b[i];
    na += a[i] * a[i];
    nb += b[i] * b[i];
  }
  return na && nb ? dot / Math.sqrt(na * nb) : 0;
}

const scored = prep.with_profile
  .map((c, i) => ({ id: c.id, name: c.name, expertise: c.expertise, score: Math.round(cosine(vectors[0], vectors[i + 1]) * 10000) / 10000 }))
  .sort((a, b) => b.score - a.score);

const top = scored.slice(0, prep.explain_top);
const system = [
  'تو دستیار مدیر گروه برای انتخاب داور پیشنهاد پروژه‌ی کارشناسی هستی.',
  'برای هر استادِ فهرست، در «یک جمله‌ی کوتاه فارسی» بنویس تخصص او چه ارتباطی با موضوع پروژه دارد.',
  'قواعد:',
  '۱. فقط از متن «تخصص» همان استاد استفاده کن و هیچ سابقه یا ویژگی دیگری از خودت نساز.',
  '۲. اگر ارتباط کم است، همین را صادقانه بنویس.',
  '۳. درباره‌ی این‌که چه کسی باید انتخاب شود نظر نده؛ تصمیم با مدیر گروه است.',
  'خروجی فقط یک شیء JSON با همین شکل باشد:',
  '{"reasons": [{"id": <شناسه‌ی عددی استاد>, "reason": "<یک جمله>"}]}',
].join('\n');
const user = [
  `موضوع پروژه:\n${prep.query_text.slice(0, 1500)}`,
  'استادان:',
  ...top.map((c) => `- id=${c.id} | ${c.name} | تخصص: ${c.expertise}`),
].join('\n');

return [
  {
    json: {
      run_id: prep.run_id,
      scored,
      llm_request: {
        model: $env.LLM_CHAT_MODEL,
        temperature: 0,
        stream: false,
        response_format: { type: 'json_object' },
        messages: [
          { role: 'system', content: system },
          { role: 'user', content: user },
        ],
      },
    },
  },
];

// گام ۵ — ترکیب امتیازها با توجیه‌های مدل. اگر مدل توجیه نداد، رتبه‌بندی بدون توجیه برمی‌گردد.
const prep = $('Prepare Candidates').first().json;
const rank = $('Rank By Similarity').first().json;
if (rank.error) {
  return [{ json: { run_id: rank.run_id, result: { error: rank.error, detail: rank.detail } } }];
}

const res = $input.first().json;
const content = res.choices && res.choices[0] && res.choices[0].message && res.choices[0].message.content;
const reasons = {};
if (content) {
  try {
    const clean = String(content).replace(/<think>[\s\S]*?<\/think>/g, '');
    const parsed = JSON.parse(clean.slice(clean.indexOf('{'), clean.lastIndexOf('}') + 1));
    for (const r of parsed.reasons || []) {
      if (r && r.reason) reasons[Number(r.id)] = String(r.reason).trim().slice(0, 400);
    }
  } catch (e) {
    // توجیه اختیاری است؛ رتبه‌بندی همچنان معتبر است
  }
}

const suggestions = [
  ...rank.scored.map((c) => ({ referee_id: c.id, score: c.score, reason: reasons[c.id] || '' })),
  ...prep.without_profile.map((c) => ({
    referee_id: c.id,
    score: null,
    reason: 'زمینه‌ی تخصصی این استاد در سامانه ثبت نشده است؛ رتبه‌بندی معنایی برای او ممکن نبود.',
  })),
];

return [
  {
    json: {
      run_id: rank.run_id,
      result: { suggestions, model: `${$env.EMBEDDING_MODEL} + ${$env.LLM_CHAT_MODEL}` },
    },
  },
];
